// Centrale foutmelding: context en verwijzing, zonder geheimen of persoonsgegevens.
const e = $input.first().json;
const exec = e.execution || {};
const wf = e.workflow || {};
const raw = String((exec.error && exec.error.message) || (e.trigger && e.trigger.error && e.trigger.error.message) || 'onbekende fout');
const redact = (s) => s
  .replace(/(Bearer\s+)[A-Za-z0-9._~+\/=-]+/gi, '$1***')
  .replace(/\b(token|password|passwd|secret|api[_-]?key|authorization|approval_code)(["'\s:=]+)[^\s"',;]+/gi, '$1$2***')
  .replace(/ssh-(ed25519|rsa) [A-Za-z0-9+\/=]+/g, 'ssh-$1 ***')
  .replace(/\b[a-z][0-9]{7}\b/gi, '<r-nummer>');
const text = [
  `Workflow:     ${wf.name || '?'} (${wf.id || '?'})`,
  `Uitvoering:   ${exec.id || '?'} (${exec.mode || '?'})`,
  `Link:         ${exec.url || '-'}`,
  `Laatste node: ${exec.lastNodeExecuted || '?'}`,
  `Tijd:         ${new Date().toISOString()}`,
  '',
  `Fout: ${redact(raw).slice(0, 800)}`,
].join('\n');
return [{ json: { subject: `n8n-fout: ${wf.name || 'workflow'} (${exec.lastNodeExecuted || '?'})`, text } }];
